//
// Host interface of the dense fp16 prefill GEMM
// (rdna_hint_flex_dense_gemm_rdna2.cu) shared with the rdna_hint_flex composite
// op: C[M, N] = A[M, K] W[N, K]^T with fp16 operands and result and fp32
// accumulation (v_dot2_f32_f16), the layout of F.linear. The kernel designs
// live in the .cu, the dispatch table (generated by
// tools/rdna/rdna_hint_flex/gemm_sweep/gen_dispatch.py) in
// rdna_hint_flex_dense_gemm_table.cuh.
#pragma once

#include <cstdint>

#include <hip/hip_runtime.h>

namespace vllm {
namespace rdna_hint_flex {
namespace gemm {

// Design ids (kDesigns in the .cu holds their names).
constexpr int kRocblas = -1;  // not a design: leave the GEMM to rocBLAS

// Modes of the composite op's `prefill_gemm` argument. 0: rocBLAS. 1: the
// dense kernel wherever the dispatch table beats rocBLAS, a short tail
// (M = kTileRows q + r) padded to a whole tile row. 2, 3, 4 also run the r tail
// rows apart from the q tile rows (a padded tile row costs 1/q of the GEMM):
// 2 on the decode GEMV (packed weights), 3 on the tail designs (fp16 scratch),
// 4 on the GEMV up to kHybridGemvMaxRows rows (the GEMV is compute-bound in r,
// the tail designs stream the whole scratch whatever r) and, from
// M = kDenseTailMinM on, on the tail designs beyond. Below that M the padded
// tile row can sit in the idle slots of the last round (M = 700 gate_up: the
// split is 6 % slower than padding).
constexpr int64_t kModeDense = 1, kModeGemvTail = 2, kModeDenseTail = 3,
                  kModeHybrid = 4;
constexpr int64_t kTileRows = 128;
constexpr int64_t kHybridGemvMaxRows = 16;
constexpr int64_t kDenseTailMinM = 1024;

// The tail designs (32x128 and 64x128 tiles, not in the table) cover up to
// kTailMaxRows rows; tail_design(rows) is kRocblas beyond that.
constexpr int64_t kTailMaxRows = 64;
int tail_design(int64_t rows);

enum class TailKind { kNone, kGemv, kDense };
// How the r = M % kTileRows tail rows of an M-row GEMM run in `mode`
// (gemv_max_rows: what the GEMV can take): kNone = inside the main GEMM's last
// (padded) tile row.
inline TailKind tail_kind(int64_t mode, int64_t m, int64_t r,
                          int64_t gemv_max_rows) {
  if (mode < kModeGemvTail || r <= 0) return TailKind::kNone;
  const bool gemv_ok = r <= gemv_max_rows;
  if (mode == kModeGemvTail) return gemv_ok ? TailKind::kGemv : TailKind::kNone;
  if (mode == kModeHybrid) {
    if (gemv_ok && r <= kHybridGemvMaxRows) return TailKind::kGemv;
    if (m < kDenseTailMinM) return TailKind::kNone;
  }
  return r <= kTailMaxRows ? TailKind::kDense : TailKind::kNone;
}

// The design the dispatch table picks for (M, N, K), or kRocblas when the
// shape is outside the validated set or rocBLAS measured faster. M is free
// (any tail), N and K select the table row.
int pick(int64_t M, int64_t N, int64_t K);

// Launch `design` on the current device (gfx1030 only). False, with nothing
// launched, when the design cannot run this problem: other architecture, K not
// a multiple of the design's K step, a pointer or row stride off 16 bytes, or
// an operand beyond the 32-bit byte offsets the kernel uses. M == 0 is a no-op.
bool launch(int design, const void* A, const void* W, void* C, int64_t M,
            int64_t N, int64_t K, int64_t lda, int64_t ldw, int64_t ldc,
            hipStream_t stream);

}  // namespace gemm
}  // namespace rdna_hint_flex
}  // namespace vllm
